application/json.schema:
{
  "title": "URL to Markdown",
  "type": "object",
  "schemaVersion": 1,
  "properties": {
    "urls": {
      "title": "URLs",
      "type": "array",
      "description": "Web pages to convert to Markdown, one per line (up to 1,000 per run). A URL without http(s):// gets https://.",
      "editor": "stringList",
      "prefill": [
        "https://en.wikipedia.org/wiki/Web_scraping",
        "https://quotes.toscrape.com/"
      ],
      "default": [
        "https://en.wikipedia.org/wiki/Web_scraping",
        "https://quotes.toscrape.com/"
      ]
    },
    "contentScope": {
      "title": "Content to keep",
      "type": "string",
      "description": "main: the page's main content (main/article), or the body without menus, headers and footers. full: the whole page body.",
      "editor": "select",
      "enum": [
        "main",
        "full"
      ],
      "enumTitles": [
        "Main content (recommended)",
        "Full page"
      ],
      "default": "main"
    },
    "cssSelector": {
      "title": "CSS selector (optional)",
      "type": "string",
      "description": "Keep only the elements matching this selector, e.g. article or #content. Overrides Content to keep.",
      "editor": "textfield"
    },
    "includeLinks": {
      "title": "Include page links",
      "type": "boolean",
      "description": "Add the page's links (URL, text, internal or external) to each row.",
      "default": false
    },
    "maxChars": {
      "title": "Max Markdown characters per page",
      "type": "integer",
      "description": "Longer Markdown is cut and the row says truncated: true.",
      "minimum": 500,
      "maximum": 2000000,
      "default": 200000
    },
    "timeoutSecs": {
      "title": "Timeout per page (seconds)",
      "type": "integer",
      "minimum": 5,
      "maximum": 30,
      "default": 15,
      "description": "How long to wait for a page to answer before it is skipped (not charged). The download may take up to 1.5x this."
    }
  },
  "required": [
    "urls"
  ]
}

